import { forwardRef, type HTMLAttributes, type ReactNode } from "react";

import { cn } from "@/lib/cn";

/** Props accepted by CountBadge. */
export type CountBadgeProps = {
  count: ReactNode;
  /** Semantic count emphasis; warnings call attention to items needing action. */
  tone?: "neutral" | "warning";
  label?: ReactNode;
} & HTMLAttributes<HTMLSpanElement>;

/** A badge displaying a caller-provided count and label. */
export const CountBadge = forwardRef<HTMLSpanElement, CountBadgeProps>(
  function CountBadge(
    { className, count, label, tone = "neutral", ...props },
    ref,
  ) {
    return (
      <span
        {...props}
        className={cn("inline-flex items-center gap-xs", className)}
        ref={ref}
      >
        <span
          className={
            tone === "warning"
              ? "badge badge-warning badge-sm tabular-nums caps-numeric"
              : "badge badge-neutral badge-sm tabular-nums caps-numeric"
          }
        >
          {count}
        </span>
        {label !== undefined ? (
          <span className="text-sm text-base-content">{label}</span>
        ) : null}
      </span>
    );
  },
);

import { STIPE_SPACING_NAMES } from "@fungi.computer/stipe";
import { cva } from "class-variance-authority";
import { createCn } from "cn/config";

/** A conditional class value accepted by cn. */
export type { ClassValue } from "cn";
export { cva };

/** Merge conditional classes with Tailwind rules and Stipe's named spacing. */
export const cn = createCn({
  extend: { theme: { spacing: [...STIPE_SPACING_NAMES] } },
});

/** Resolve a typed React class-name prop before merging its classes. */
export function resolveClassName<State>(
  className: string | ((state: State) => string | undefined) | undefined,
  state: State,
): string | undefined {
  return typeof className === "function" ? className(state) : className;
}
